<script setup lang="ts">
import { computed, onBeforeUnmount, watch, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ArrowDown, ArrowUp, Pencil, Plus, Trash2, X } from 'lucide-vue-next'
import { AI_SHORTCUT_LABEL_MAX_LENGTH, AI_SHORTCUT_PROMPT_MAX_LENGTH, type AiShortcutAction } from '@/services/aiShortcutActions'
import { useSettingsStore } from '@/stores/settingsStore'
import { useZustandSelector } from '@/composables/useZustandSelector'
import { toast } from '@/services/toast'

type Draft = { id: string | null; label: string; prompt: string }
const { t } = useI18n()
const actions = useZustandSelector(useSettingsStore, (state) => state.aiShortcutActions)
const draft = ref<Draft | null>(null)
const errors = ref<{ label?: string; prompt?: string }>({})
const editorClosing = ref(false)
let closeTimer: number | undefined
const editorOpen = computed(() => draft.value !== null)
function createId(): string { return `ai-shortcut-${Date.now()}-${Math.random().toString(36).slice(2, 8)}` }
function closeEditor(): void { if (!editorOpen.value || editorClosing.value) return; editorClosing.value = true; closeTimer = window.setTimeout(() => { draft.value = null; errors.value = {}; editorClosing.value = false }, 160) }
function openCreate(): void { errors.value = {}; editorClosing.value = false; draft.value = { id: null, label: '', prompt: '' } }
function openEdit(action: AiShortcutAction): void { errors.value = {}; editorClosing.value = false; draft.value = { id: action.id, label: action.label, prompt: action.prompt } }
function saveDraft(): void { const value = draft.value; if (!value) return; const label = value.label.trim(), prompt = value.prompt.trim(); const next = { label: !label ? t('aiShortcutSettings.nameRequired') : label.length > AI_SHORTCUT_LABEL_MAX_LENGTH ? t('aiShortcutSettings.nameTooLong', { max: AI_SHORTCUT_LABEL_MAX_LENGTH }) : undefined, prompt: !prompt ? t('aiShortcutSettings.promptRequired') : prompt.length > AI_SHORTCUT_PROMPT_MAX_LENGTH ? t('aiShortcutSettings.promptTooLong', { max: AI_SHORTCUT_PROMPT_MAX_LENGTH }) : undefined }; if (next.label || next.prompt) { errors.value = next; return } const state = useSettingsStore.getState(); state.setAiShortcutActions(value.id ? actions.value.map((item) => item.id === value.id ? { ...item, label, prompt } : item) : [...actions.value, { id: createId(), label, prompt, enabled: true }]); toast.success(value.id ? t('aiShortcutSettings.updated') : t('aiShortcutSettings.added')); closeEditor() }
function toggleAction(id: string, enabled: boolean): void { useSettingsStore.getState().setAiShortcutActions(actions.value.map((item) => item.id === id ? { ...item, enabled } : item)) }
function moveAction(from: number, to: number): void { if (from === to || to < 0 || to >= actions.value.length) return; const next = [...actions.value], [moved] = next.splice(from, 1); next.splice(to, 0, moved); useSettingsStore.getState().setAiShortcutActions(next) }
function removeAction(action: AiShortcutAction): void { if (!window.confirm(t('aiShortcutSettings.deleteConfirm', { label: action.label }))) return; useSettingsStore.getState().setAiShortcutActions(actions.value.filter((item) => item.id !== action.id)); toast.success(t('aiShortcutSettings.deleted')) }
function resetActions(): void { if (!window.confirm(t('aiShortcutSettings.resetConfirm'))) return; useSettingsStore.getState().resetAiShortcutActions(); toast.success(t('aiShortcutSettings.reset')) }
function keydown(event: KeyboardEvent): void { if (event.key === 'Escape') closeEditor() }
watch(editorOpen, (open) => { if (open) document.addEventListener('keydown', keydown, true); else document.removeEventListener('keydown', keydown, true) })
onBeforeUnmount(() => { document.removeEventListener('keydown', keydown, true); if (closeTimer) window.clearTimeout(closeTimer) })
</script>

<template>
  <section class="gm-vue-settings-section">
    <header class="gm-vue-shortcut-header"><div><h3>{{ t('aiShortcutSettings.title') }}</h3><p>{{ t('aiShortcutSettings.description') }}</p></div><div><button type="button" @click="resetActions">{{ t('aiShortcutSettings.restoreDefaults') }}</button><button type="button" class="gm-vue-settings-primary" @click="openCreate"><Plus :size="14" />{{ t('aiShortcutSettings.addAction') }}</button></div></header>
    <div v-if="!actions.length" class="gm-vue-settings-empty">{{ t('aiShortcutSettings.empty') }}</div>
    <article v-for="(action, index) in actions" :key="action.id" class="gm-vue-shortcut-row" :data-ai-shortcut-row="action.id"><div class="gm-vue-shortcut-order"><button type="button" :disabled="index === 0" :aria-label="t('aiShortcutSettings.moveUp', { label: action.label })" @click="moveAction(index, index - 1)"><ArrowUp :size="13" /></button><button type="button" :disabled="index === actions.length - 1" :aria-label="t('aiShortcutSettings.moveDown', { label: action.label })" @click="moveAction(index, index + 1)"><ArrowDown :size="13" /></button></div><div class="gm-vue-shortcut-row__copy"><b>{{ action.label }}</b><span>{{ action.prompt }}</span></div><label class="gm-vue-switch"><input type="checkbox" :checked="action.enabled" @change="toggleAction(action.id, ($event.target as HTMLInputElement).checked)" /><i /></label><button type="button" :title="t('aiShortcutSettings.edit')" @click="openEdit(action)"><Pencil :size="14" /></button><button type="button" :title="t('aiShortcutSettings.delete')" class="gm-vue-settings-danger" @click="removeAction(action)"><Trash2 :size="14" /></button></article>
  </section>
  <div v-if="draft" class="gm-vue-settings-scrim" :data-closing="editorClosing || undefined" @mousedown.self="closeEditor"><section class="gm-vue-settings-dialog" role="dialog" aria-modal="true" aria-labelledby="ai-shortcut-dialog-title"><header><h2 id="ai-shortcut-dialog-title">{{ draft.id ? t('aiShortcutSettings.editTitle') : t('aiShortcutSettings.addTitle') }}</h2><button type="button" :title="t('aiShortcutSettings.close')" @click="closeEditor"><X :size="16" /></button></header><label>{{ t('aiShortcutSettings.nameLabel') }}<input v-model="draft.label" :maxlength="AI_SHORTCUT_LABEL_MAX_LENGTH" :placeholder="t('aiShortcutSettings.namePlaceholder')" @input="errors.label = undefined" /><small :class="{ 'gm-vue-settings-error': errors.label }">{{ errors.label || `${draft.label.length}/${AI_SHORTCUT_LABEL_MAX_LENGTH}` }}</small></label><label>{{ t('aiShortcutSettings.promptLabel') }}<textarea v-model="draft.prompt" :maxlength="AI_SHORTCUT_PROMPT_MAX_LENGTH" :placeholder="t('aiShortcutSettings.promptPlaceholder')" @input="errors.prompt = undefined" /><small :class="{ 'gm-vue-settings-error': errors.prompt }">{{ errors.prompt || `${draft.prompt.length}/${AI_SHORTCUT_PROMPT_MAX_LENGTH}` }}</small></label><footer><button type="button" @click="closeEditor">{{ t('aiShortcutSettings.cancel') }}</button><button type="button" class="gm-vue-settings-primary" @click="saveDraft">{{ t('aiShortcutSettings.save') }}</button></footer></section></div>
</template>

<style scoped>
.gm-vue-settings-section { display: grid; gap: 10px; padding-bottom: 18px; }.gm-vue-shortcut-header { display: flex; flex-wrap: wrap; align-items: start; justify-content: space-between; gap: 12px; }.gm-vue-shortcut-header h3 { margin: 0; color: var(--gm-text-tertiary); font-size: var(--gm-text-xs); text-transform: uppercase; }.gm-vue-shortcut-header p { max-width: 520px; margin: 5px 0 0; color: var(--gm-text-secondary); font-size: var(--gm-text-sm); }.gm-vue-shortcut-header > div:last-child,.gm-vue-settings-dialog footer { display: flex; gap: 7px; }.gm-vue-shortcut-header button,.gm-vue-shortcut-row > button,.gm-vue-settings-dialog button { padding: 6px 9px; color: var(--gm-text-secondary); border: 1px solid var(--gm-border); border-radius: var(--gm-radius-sm); background: var(--gm-surface); font-size: var(--gm-text-xs); }.gm-vue-settings-primary { color: var(--gm-text-on-primary) !important; border-color: var(--gm-primary) !important; background: var(--gm-primary) !important; }.gm-vue-shortcut-row { display: flex; min-width: 0; padding: 9px; align-items: center; gap: 8px; border: 1px solid var(--gm-border); border-radius: var(--gm-radius-md); background: var(--gm-surface-elevated); }.gm-vue-shortcut-order { display: grid; }.gm-vue-shortcut-order button { display: grid; width: 22px; height: 18px; padding: 0; place-items: center; color: var(--gm-text-tertiary); border: 0; background: transparent; }.gm-vue-shortcut-order button:disabled { opacity: .35; }.gm-vue-shortcut-row__copy { display: grid; min-width: 0; flex: 1; gap: 3px; }.gm-vue-shortcut-row__copy b,.gm-vue-shortcut-row__copy span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.gm-vue-shortcut-row__copy b { color: var(--gm-text); font-size: var(--gm-text-sm); }.gm-vue-shortcut-row__copy span { color: var(--gm-text-tertiary); font-size: var(--gm-text-xs); }.gm-vue-switch { position: relative; width: 34px; height: 20px; flex: 0 0 auto; }.gm-vue-switch input { position: absolute; opacity: 0; }.gm-vue-switch i { position: absolute; inset: 0; border-radius: 999px; background: var(--gm-border); }.gm-vue-switch i::after { position: absolute; top: 3px; left: 3px; width: 14px; height: 14px; border-radius: 50%; background: white; content: ''; transition: transform .15s; }.gm-vue-switch input:checked + i { background: var(--gm-primary); }.gm-vue-switch input:checked + i::after { transform: translateX(14px); }.gm-vue-settings-danger { color: var(--gm-error) !important; }.gm-vue-settings-empty { padding: 24px; color: var(--gm-text-secondary); border: 1px dashed var(--gm-border); border-radius: var(--gm-radius-md); text-align: center; font-size: var(--gm-text-sm); }.gm-vue-settings-scrim { position: fixed; z-index: 1100; inset: 0; display: grid; padding: 16px; place-items: center; background: rgb(0 0 0 / 45%); }.gm-vue-settings-dialog { display: grid; width: min(560px, 100%); gap: 15px; padding: 18px; border: 1px solid var(--gm-border); border-radius: var(--gm-radius-lg); background: var(--gm-surface); box-shadow: var(--gm-shadow-lg); }.gm-vue-settings-dialog header { display: flex; align-items: center; justify-content: space-between; }.gm-vue-settings-dialog h2 { margin: 0; color: var(--gm-text); font-size: var(--gm-text-lg); }.gm-vue-settings-dialog header button { display: grid; padding: 5px; place-items: center; }.gm-vue-settings-dialog label { display: grid; gap: 6px; color: var(--gm-text); font-size: var(--gm-text-sm); font-weight: 700; }.gm-vue-settings-dialog input,.gm-vue-settings-dialog textarea { width: 100%; box-sizing: border-box; padding: 8px 10px; color: var(--gm-text); border: 1px solid var(--gm-border); border-radius: var(--gm-radius-sm); background: var(--gm-canvas); font: inherit; font-weight: 400; }.gm-vue-settings-dialog textarea { min-height: 140px; resize: vertical; }.gm-vue-settings-dialog small { color: var(--gm-text-tertiary); font-weight: 400; }.gm-vue-settings-error { color: var(--gm-error) !important; }.gm-vue-settings-dialog footer { justify-content: end; }
</style>
